#define wmain ProbeMain
#include "../../benchmarks/shell-content-guard-probe.cpp"
#undef wmain

int wmain(int argc, wchar_t** argv) {
    if (argc != 3) return 2;
    HRESULT initialized = CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED);
    if (FAILED(initialized)) return 3;
    int result = 1;
    try {
        wchar_t temporary[32768]{};
        DWORD length = GetTempPathW(32768, temporary);
        Require(length > 0 && length < 32768);
        const auto expected = std::wstring(temporary) + L"voldiq-shell-guard-{9D2E38F5-34AB-4E57-8E13-78CACB84A322}";
        Require(expected == argv[2]);
        auto retained = Open(argv[1], GENERIC_READ, 7);
        auto original = Identity(retained.get());
        ReadOriginal(retained.get());
        retained.reset();
        WinCheck(CreateDirectoryW(expected.c_str(), nullptr) != FALSE);
        auto sink = Microsoft::WRL::Make<Sink>();
        Require(sink != nullptr);
        auto operation = Operation(FOF_SILENT | FOF_NOCONFIRMATION | FOF_NOERRORUI | FOF_RENAMEONCOLLISION | FOFX_EARLYFAILURE);
        auto source = Item(argv[1]);
        auto parent = Item(expected);
        Check(operation->MoveItem(source.Get(), parent.Get(), L"baseline.bin", sink.Get()));
        HRESULT performed = operation->PerformOperations();
        BOOL aborted = TRUE;
        Check(operation->GetAnyOperationsAborted(&aborted));
        Require(SUCCEEDED(performed) && !aborted && sink->moveCalls == 1 && SUCCEEDED(sink->moveResult));
        {
            auto restored = Open(expected + L"\\baseline.bin", GENERIC_READ | DELETE, FILE_SHARE_READ);
            Require(Same(original, Identity(restored.get())));
            ReadOriginal(restored.get());
            FILE_DISPOSITION_INFO disposition{TRUE};
            WinCheck(SetFileInformationByHandle(restored.get(), FileDispositionInfo, &disposition, sizeof(disposition)) != FALSE);
        }
        Require(!Exists(expected + L"\\baseline.bin"));
        WinCheck(RemoveDirectoryW(expected.c_str()) != FALSE);
        std::printf("{\"recovered\":true,\"sameIdentity\":true,\"contentPreserved\":true,\"fixtureCleaned\":true}\n");
        result = 0;
    } catch (HRESULT error) { std::printf("{\"error\":\"0x%08lx\"}\n", static_cast<unsigned long>(error)); }
    CoUninitialize();
    return result;
}
